package com.crypto.laplace.stop;
import com.crypto.binance.client.BinanceFuturesClient; import com.crypto.common.enums.PositionSide; import com.crypto.domain.model.Kline; import com.crypto.laplace.execution.*; import com.crypto.laplace.model.LaplacePositionStatus; import com.crypto.laplace.persistence.*; import com.crypto.laplace.pool.LaplaceCoinPoolService; import java.math.*; import java.time.*; import java.util.*; import lombok.RequiredArgsConstructor; import lombok.extern.slf4j.Slf4j; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Slf4j @Service @RequiredArgsConstructor public class LaplaceFiveMinuteStopService { private final BinanceFuturesClient client; private final LaplacePaperPositionRepository positions; private final LaplacePnlCalculator pnl; private final LaplaceCoinPoolService pool;
 public void checkOpenPositions(){Instant start=Instant.now();List<LaplacePaperPositionEntity> open=positions.findByStrategyAndStatus(LaplacePaperExecutionService.STRATEGY,LaplacePositionStatus.OPEN);int candles=0, stopped=0;Set<String> errors=new HashSet<>();for(var p:open)try{candles+=check(p)?1:0;if(p.getStatus()==LaplacePositionStatus.CLOSED_BY_STOP_LOSS)stopped++;}catch(RuntimeException e){errors.add(p.getSymbol());log.error("LAPLACE_STOP_CANDLE_LOAD_FAILED symbol={} positionId={}",p.getSymbol(),p.getId(),e);}log.info("LAPLACE_5M_STOP_CHECK openPositions={} symbols={} candles={} stopped={} apiErrors={} startedAt={} finishedAt={}",open.size(),open.stream().map(LaplacePaperPositionEntity::getSymbol).distinct().count(),candles,stopped,errors,start,Instant.now());}
 private boolean check(LaplacePaperPositionEntity p){List<Kline> all=client.getKlines(p.getSymbol(),"5m",40);Instant now=Instant.now();Instant entryFloor=p.getEntryTime().truncatedTo(java.time.temporal.ChronoUnit.HOURS).plusSeconds((p.getEntryTime().getEpochSecond()%3600/300+1)*300);Instant after=p.getLastChecked5mCandleCloseTime()==null?entryFloor:p.getLastChecked5mCandleCloseTime();List<Kline> closed=all.stream().filter(c->c!=null&&c.getCloseTime()!=null&&!c.getCloseTime().isAfter(now)&&!Boolean.FALSE.equals(c.getClosed())&&c.getCloseTime().isAfter(after)).sorted(Comparator.comparing(Kline::getCloseTime)).toList();for(Kline c:closed){boolean hit=p.getSide()==PositionSide.LONG?c.getLow().compareTo(p.getStopPrice())<=0:c.getHigh().compareTo(p.getStopPrice())>=0;if(hit){closeStop(p.getId(),c);return true;} p.setLastChecked5mCandleCloseTime(c.getCloseTime());positions.save(p);}return false;}
 @Transactional public void closeStop(String id,Kline c){LaplacePaperPositionEntity p=positions.findById(id).orElseThrow();if(p.getStatus()!=LaplacePositionStatus.OPEN)return;BigDecimal exit=p.getStopPrice();BigDecimal exitFee=p.getQuantity().multiply(exit).multiply(p.getEntryFeeRate()).setScale(12,RoundingMode.HALF_UP);var r=pnl.calculate(p.getSide(),p.getEntryExecutionPrice(),exit,p.getQuantity(),p.getNotional(),p.getEntryFee(),exitFee);p.setStatus(LaplacePositionStatus.CLOSED_BY_STOP_LOSS);p.setExitReason("STOP_LOSS_5M");p.setExitTime(c.getCloseTime());p.setExitExecutionPrice(exit);p.setExitFee(exitFee);p.setGrossPnl(r.gross());p.setGrossPnlPct(r.grossPct());p.setNetPnl(r.net());p.setNetPnlPct(r.netPct());p.setStopTriggeredCandleOpenTime(c.getOpenTime());p.setStopTriggeredCandleCloseTime(c.getCloseTime());p.setStopTriggeredCandleHigh(c.getHigh());p.setStopTriggeredCandleLow(c.getLow());p.setStopTriggeredCandleClose(c.getClose());positions.saveAndFlush(p);pool.positionClosed(p.getSymbol());log.info("LAPLACE_STOP_TRIGGERED positionId={} symbol={} side={} entryPrice={} stopPrice={} candleOpenTime={} candleCloseTime={} candleHigh={} candleLow={} candleClose={} exitPrice={} grossPnl={} entryFee={} exitFee={} netPnl={}",p.getId(),p.getSymbol(),p.getSide(),p.getEntryExecutionPrice(),p.getStopPrice(),c.getOpenTime(),c.getCloseTime(),c.getHigh(),c.getLow(),c.getClose(),exit,r.gross(),p.getEntryFee(),exitFee,r.net()); }
}
